export const getRandomQuestion = (monsterId) => {
  const pool = QUESTIONS_DATA[monsterId];
  if (!pool || pool.length === 0) return null;
  const randomIndex = Math.floor(Math.random() * pool.length);
  return pool[randomIndex];
};
